const usersWithDueLots = `-- name: UsersWithDueLots :many
SELECT DISTINCT user_id FROM billing.credit_lots
WHERE (next_decay_at IS NOT NULL AND next_decay_at <= $1::timestamptz)
   OR (expires_at IS NOT NULL AND expires_at <= $1::timestamptz AND remaining > 0)
LIMIT $2
`

type UsersWithDueLotsParams struct {
	Now       pgtype.Timestamptz `json:"now"`
	BatchSize int32              `json:"batch_size"`
}

func (q *Queries) UsersWithDueLots(ctx context.Context, arg UsersWithDueLotsParams) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, usersWithDueLots, arg.Now, arg.BatchSize)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []uuid.UUID
	for rows.Next() {
		var user_id uuid.UUID
		if err := rows.Scan(&user_id); err != nil {
			return nil, err
		}
		items = append(items, user_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
